"""Synthetic checks for requested defaults, device toggles, admin contrast, signer search and printed pass."""
import asyncio,json,hashlib,fitz
from playwright.async_api import async_playwright
HOST='http://127.0.0.1:8010'
async def main():
 async with async_playwright() as pw:
  b=await pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);ctx=await b.new_context(viewport={'width':1440,'height':1100});await ctx.route('https://**/*',lambda r:r.abort());p=await ctx.new_page();errors=[];p.on('pageerror',lambda e:errors.append(str(e)))
  endpoint='https://fcm.googleapis.com/fcm/send/sicip-synthetic-device';device=hashlib.sha256(endpoint.encode()).hexdigest();state={'active':True}
  await ctx.add_init_script('''(()=>{if(window.top!==window)return;window.__testSubActive=true;const endpoint='''+json.dumps(endpoint)+''';const sub={endpoint,options:{},toJSON:()=>({endpoint,keys:{p256dh:'synthetic',auth:'synthetic'}}),unsubscribe:async()=>{window.__testSubActive=false;return true;}};const reg={update:async()=>{},pushManager:{getSubscription:async()=>window.__testSubActive?sub:null,subscribe:async()=>{window.__testSubActive=true;return sub;}}};Object.defineProperty(Notification,'permission',{get:()=> 'granted'});Notification.requestPermission=async()=> 'granted';navigator.serviceWorker.getRegistration=async()=>reg;Object.defineProperty(navigator.serviceWorker,'ready',{get:()=>Promise.resolve(reg)});})();''')
  await ctx.route('**/api/notificaciones/config',lambda r:r.fulfill(json={'push_disponible':True,'correo_disponible':False,'clave_publica':'BAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA','dispositivos':[{'id':device}] if state['active'] else []}))
  async def subscription(r):state['active']=r.request.method!='DELETE';await r.fulfill(json={'ok':True})
  await ctx.route('**/api/notificaciones/suscripcion',subscription)
  async def api(path,method='GET',d=None):return await p.evaluate('(x)=>window.SICIPCentral.api(x.p,{method:x.m,...(x.d?{body:JSON.stringify(x.d)}:{})})',{'p':path,'m':method,'d':d})
  async def login(mat):
   await p.goto(HOST+'/login');await p.locator('input[type=text]').first.fill(mat);await p.locator('input[type=password]').fill('PruebaSegura123!');await p.get_by_role('button',name='Iniciar Sesión',exact=True).click();await p.locator('.home-metrics').wait_for()
  await login('TESTADMIN');assert await p.locator('[data-home-refresh]').count()==0;await p.evaluate('window.SICIPPWA.checkUpdate()');assert await p.locator('[data-app-update]').count()==0
  toggle=p.locator('[data-device-toggle]');await p.get_by_role('button',name='Desactivar avisos en este dispositivo',exact=True).wait_for();await toggle.click();await p.get_by_role('button',name='Activar avisos en este dispositivo',exact=True).wait_for();await toggle.click();await p.get_by_role('button',name='Desactivar avisos en este dispositivo',exact=True).wait_for();assert state['active'];print('Inicio sin Actualizar permanente; permisos concedidos muestran Desactivar, con alternancia real comprobada.',flush=True)
  await p.goto(HOST+'/admin');await p.locator('.admin-unified-tabs').wait_for()
  for text in ['Personal y Plazas','Jornadas y tabuladores','Historial de cortes','Nombres de las unidades','Catálogo de recepción','Supervisión de cálculos']:
   button=p.locator('.admin-unified-tabs').get_by_role('button',name=text,exact=True);await button.click();await p.wait_for_timeout(100);assert await button.evaluate("e=>getComputedStyle(e).color==='rgb(255, 255, 255)'&&['rgb(0, 82, 53)','rgb(0, 68, 45)'].includes(getComputedStyle(e).backgroundColor)")
  await api('/api/admin/unidades','POST',{'clave':'H1','nombre':'HOSPITAL GENERAL DE ZONA No. 1','activo':True,'version':0});await api('/api/admin/unidades/asignar','POST',{'unidad':'H1','matriculas':['TESTUSER']})
  # Historical record predates the unit assignment; reading/printing must enrich it without losing its other fields.
  row=await api('/api/pases/registros','POST',{'folio':'HISTORICO-UX545','matricula':'TESTUSER','nombre':'Trabajador de prueba','categoria':'CATEGORÍA','servicio':'SERVICIO','fecha':'2026-11-11','hora':'12:00','tipoAsunto':'PARTICULAR','tipoHorario':'SALIDA','estado':'PENDIENTE_ENTREGA','objeto':'PRUEBA'})
  passes=await ctx.new_page();passes.on('pageerror',lambda e:errors.append(str(e)));await passes.add_init_script('window.print=()=>window.__printed=true');await passes.goto(HOST+'/pases/index.html?scope=personal');await passes.locator('[data-pass-path=nuevo]').wait_for();assert not await passes.locator('#passForm').is_visible();assert not await passes.locator('#manualForm').is_visible();await passes.locator('[data-pass-path=manual]').click();assert await passes.locator('#manualForm').is_visible();assert not await passes.locator('#passForm').is_visible();await passes.locator('[data-pass-path=nuevo]').click();assert await passes.locator('#passForm').is_visible();assert not await passes.locator('#manualForm').is_visible();assert await passes.locator('#buscarJefe,#buscarPersonal').count()==0
  for name,mat in [('Jefe inmediato · nombre o matrícula','TESTADMIN'),('Responsable de Personal · nombre o matrícula','TESTUSER')]:
   await passes.get_by_role('combobox',name=name,exact=True).fill(mat);await passes.get_by_role('option').filter(has_text=mat).click()
  assert 'Administración de prueba' in await passes.locator('.signer-search [data-signer-summary]').first.inner_text();assert 'Cargo:' in await passes.locator('.signer-search [data-signer-summary]').first.inner_text()
  await passes.wait_for_function('window.SICIPPasesStorage.read().some(p=>p.folio==="HISTORICO-UX545")');await passes.evaluate('window.SICIPPases.print("HISTORICO-UX545")');await passes.wait_for_function('window.__printed');assert 'HOSPITAL GENERAL DE ZONA No. 1' in await passes.locator('.pass-Head').inner_text();pdf=await passes.pdf(format='Letter',print_background=True,prefer_css_page_size=True,display_header_footer=True);doc=fitz.open(stream=pdf,filetype='pdf');assert len(doc)==1;assert HOST not in doc[0].get_text();assert 'SICIP — Módulo de Pases' not in doc[0].get_text();assert 'HOSPITAL GENERAL DE ZONA No. 1' in doc[0].get_text();open('/workspace/sicip-env/pase-545.pdf','wb').write(pdf);print('Administración legible; flujo nuevo/manual separado; firmantes en un campo; unidad en pase y PDF sin encabezado/pie del navegador comprobados.',flush=True)
  await login('TESTUSER');u=await api('/api/session');assert u['usuario']['accesos']==['inicio','tramites.seguimiento','solicitudes.pases'];await p.wait_for_timeout(500);assert not await p.locator('[data-worker-pecv-nav]').is_visible();assert not await p.locator('[data-sicip-depto-btn]').is_visible();assert await p.locator('nav.sidebar').get_by_role('button',name='Cuadros de Reemplazo',exact=False).count()==0;assert await p.locator('nav.sidebar').get_by_role('button',name='Exámenes',exact=True).count()==0;assert await p.locator('nav.sidebar').get_by_role('button',name='Inicio',exact=True).is_visible();assert await p.locator('nav.sidebar').get_by_role('button',name='Mis Trámites',exact=True).is_visible();await p.set_viewport_size({'width':390,'height':844});assert await p.evaluate('document.documentElement.scrollWidth<=innerWidth+1');assert not errors,errors;await b.close();print('Permisos del trabajador y diseño móvil comprobados.',flush=True)
asyncio.run(main())
